            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    marker = min((value for value in counts if value != background),
                 key=lambda value: counts[value])

    out = [row[:] for row in grid]
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        if len(cols) >= 2:
            for c in range(min(cols) + 1, max(cols)):
                if out[r][c] == background:
